<div x-show="detailModalOpen" class="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4 backdrop-blur-[1px]" role="dialog" aria-modal="true"><div  class="flex max-h-[85vh] w-full max-w-xl flex-col overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-xl"><header class="flex items-center justify-between border-b border-gray-100 px-6 py-4"><div><p class="text-[11px] font-semibold uppercase tracking-wider text-gray-400">APPLICATION DETAIL</p><p class="text-sm font-bold text-blue-600" x-text="selectedApp?.reference"></p></div><button type="button" @click="detailModalOpen = false" class="text-gray-500 hover:text-gray-900" aria-label="Close"><svg class="h-6 w-6" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path stroke-linecap="round" d="m6 6 12 12M18 6 6 18"/></svg></button></header><div class="space-y-4 overflow-y-auto p-6"><div class="flex items-start justify-between"><div><h2 class="text-xl font-bold text-gray-900" x-text="`${selectedApp?.lastName}, ${selectedApp?.firstName} ${selectedApp?.middleName}`"></h2><p class="mt-0.5 text-xs text-gray-500" x-text="`Submitted ${selectedApp?.submitted} · ${selectedApp?.barangay}`"></p></div><div class="flex flex-col items-end gap-1.5"><span class="rounded-md bg-blue-50 px-2.5 py-0.5 text-xs font-semibold text-blue-600">New ID</span><span class="inline-flex items-center gap-1.5 rounded-full border px-3 py-1 text-xs font-semibold" :class="{'bg-amber-50 text-amber-700 border-amber-100': selectedApp?.status === 'Under Review', 'bg-blue-50 text-blue-600 border-blue-100': selectedApp?.status === 'Approved/For Printing', 'bg-emerald-50 text-emerald-700 border-emerald-100': selectedApp?.status === 'Ready for Claiming', 'bg-gray-100 text-gray-600 border-gray-200': selectedApp?.status === 'Released', 'bg-red-50 text-red-700': selectedApp?.status === 'Rejected'}"><i class="h-1.5 w-1.5 rounded-full" :class="{'bg-amber-500': selectedApp?.status === 'Under Review', 'bg-blue-600': selectedApp?.status === 'Approved/For Printing', 'bg-emerald-500': selectedApp?.status === 'Ready for Claiming', 'bg-gray-500': selectedApp?.status === 'Released', 'bg-red-500': selectedApp?.status === 'Rejected'}"></i><span x-text="selectedApp?.status"></span></span></div></div><div x-show="selectedApp?.status === 'Rejected'" class="space-y-1.5 rounded-2xl border border-red-200 bg-red-50/80 p-4"><p class="flex items-center gap-2"><svg class="h-4 w-4 text-red-600" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="12" r="9"/><path stroke-linecap="round" d="M12 8v5m0 3h.01"/></svg><span class="text-xs font-bold uppercase tracking-wider text-red-700">APPLICATION REJECTED</span></p><p class="text-sm font-medium text-red-800" x-text="selectedApp?.rejectionNote || 'Duplicate record found — applicant already has an active OSCA ID.'"></p><p class="text-xs text-red-600" x-text="'Rejected by: ' + (selectedApp?.rejectedBy || 'Maria A. (OSCA Staff)') + ' · ' + (selectedApp?.rejectedAt || 'Sep 22, 2026 at 2:40 PM')"></p></div><div class="rounded-2xl border border-gray-200 p-5"><p class="mb-4 text-xs font-semibold uppercase tracking-wider text-gray-400">PERSONAL INFORMATION</p><div class="grid grid-cols-3 gap-x-4 gap-y-4"><div><p class="field-label">LAST NAME</p><p x-text="selectedApp?.lastName"></p></div><div><p class="field-label">FIRST NAME</p><p x-text="selectedApp?.firstName"></p></div><div><p class="field-label">MIDDLE NAME</p><p x-text="selectedApp?.middleName"></p></div><div><p class="field-label">DATE OF BIRTH</p><p x-text="selectedApp?.birthDate"></p></div><div><p class="field-label">AGE</p><p x-text="selectedApp?.age + ' years old'"></p></div><div><p class="field-label">SEX</p><p x-text="selectedApp?.sex"></p></div></div></div><div class="rounded-2xl border border-gray-200 p-5"><p class="mb-4 text-xs font-semibold uppercase tracking-wider text-gray-400">ADDRESS &amp; CONTACT</p><div class="grid grid-cols-3 gap-x-4 gap-y-4"><div><p class="field-label">PROVINCE</p><p>Bulacan</p></div><div><p class="field-label">MUNICIPALITY</p><p>Santa Maria</p></div><div><p class="field-label">BARANGAY</p><p x-text="selectedApp?.barangay"></p></div><div><p class="field-label">MOBILE NUMBER</p><p x-text="selectedApp?.mobile"></p></div><div class="col-span-2"><p class="field-label">STREET / HOUSE NO.</p><p x-text="selectedApp?.street"></p></div></div></div><div class="space-y-3 rounded-2xl border border-gray-200 p-5"><p class="text-xs font-semibold uppercase tracking-wider text-gray-400">APPLICATION TYPE</p><p class="flex items-center gap-2 font-bold text-gray-800"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="8" r="3"/><path stroke-linecap="round" d="M5 20a7 7 0 0 1 14 0"/></svg><span x-text="selectedApp?.applicantType"></span></p><div x-show="selectedApp?.applicantType === 'Proxy / Representative'" class="grid grid-cols-2 gap-x-4 gap-y-3 rounded-xl border border-amber-200/80 bg-amber-50/60 p-4"><div><p class="field-label">PROXY NAME</p><p x-text="selectedApp?.proxyName"></p></div><div><p class="field-label">RELATIONSHIP</p><p x-text="selectedApp?.proxyRelationship"></p></div><div class="col-span-2"><p class="field-label">PROXY CONTACT</p><p x-text="selectedApp?.proxyMobile"></p></div></div></div><div class="rounded-2xl border border-gray-200 p-5"><p class="mb-3 text-xs font-semibold uppercase tracking-wider text-gray-400">UPLOADED INFORMATION</p><p class="mb-2 text-xs font-semibold uppercase text-gray-500">1×1 ID PHOTO</p><div class="flex h-24 w-24 flex-col items-center justify-center overflow-hidden rounded-xl border-2 border-dashed border-gray-200 bg-gray-50/50 text-gray-400"><template x-if="selectedApp?.photoUrl"><img :src="selectedApp.photoUrl" alt="Applicant photo" class="h-full w-full object-cover"></template><template x-if="!selectedApp?.photoUrl"><div class="flex flex-col items-center"><svg class="h-6 w-6" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8" cy="9" r="1.5"/><path stroke-linecap="round" d="m4 18 5-5 3 3 2-2 6 5"/></svg><span class="mt-1 text-[11px]">No photo</span></div></template></div></div><div class="rounded-2xl border border-gray-200 p-5"><p class="mb-4 text-xs font-semibold uppercase tracking-wider text-gray-400">PROCESSING STAGE</p><div class="space-y-0"><template x-for="(stage, index) in ['Under Review','Approved/For Printing','Ready for Claiming','Released']" :key="stage"><div class="flex gap-3"><div class="flex flex-col items-center"><span class="flex h-8 w-8 items-center justify-center rounded-full border-2 text-sm font-semibold" :class="index <= ['Under Review','Approved/For Printing','Ready for Claiming','Released'].indexOf(selectedApp?.status) ? 'border-blue-600 bg-white text-blue-600' : 'border-gray-200 bg-white text-gray-400'" x-text="index + 1"></span><span x-show="index < 3" class="h-7 w-px bg-gray-200"></span></div><div class="pt-1"><p class="text-sm font-semibold" :class="index <= ['Under Review','Approved/For Printing','Ready for Claiming','Released'].indexOf(selectedApp?.status) ? 'text-blue-600' : 'text-gray-400'" x-text="stage"></p><p class="text-[11px] text-gray-400" x-text="stage === selectedApp?.status ? 'Current stage' : (index < ['Under Review','Approved/For Printing','Ready for Claiming','Released'].indexOf(selectedApp?.status) ? 'Completed' : 'Pending')"></p></div></div></template></div></div></div><footer class="border-t border-gray-100 bg-white px-6 py-4"><template x-if="['Under Review','Approved/For Printing','Ready for Claiming'].includes(selectedApp?.status)"><div><button type="button" @click="confirmStageModalOpen = true" class="w-full rounded-xl bg-blue-600 py-2.5 text-sm font-semibold text-white transition-all hover:bg-blue-700" x-text="selectedApp?.status === 'Under Review' ? 'Approve & Queue for Printing' : selectedApp?.status === 'Approved/For Printing' ? 'Mark as Ready for Claiming' : 'Release Physical ID Card'"></button><button type="button" @click="rejectModalOpen = true; rejectReasonInput = ''; confirmRejectStep = false" class="mt-2.5 w-full cursor-pointer rounded-xl border border-red-200 py-2.5 text-sm font-semibold text-red-600 transition-all hover:bg-red-50">Reject</button></div></template><template x-if="selectedApp?.status === 'Released'"><div class="flex w-full items-center justify-center gap-1.5 py-1.5 text-sm font-semibold text-emerald-600">✓ ID released and archived</div></template><template x-if="selectedApp?.status === 'Rejected'"><div class="flex w-full items-center justify-center gap-1.5 py-1.5 text-sm font-semibold text-red-600">✕ Application rejected</div></template></footer></div></div>
<div x-show="confirmStageModalOpen" class="fixed inset-0 z-[70] flex items-center justify-center bg-black/40 p-4"><div  class="w-full max-w-md space-y-4 rounded-2xl border border-gray-200 bg-white p-6 shadow-2xl"><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-50 text-blue-600"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path stroke-linecap="round" d="m12 5 7 7-7 7M5 12h14"/></svg></span><h3 class="text-base font-bold text-gray-900">Are you sure?</h3></div><p class="text-sm text-gray-500">Are you sure you want to advance <span class="font-bold text-gray-900" x-text="selectedApp?.lastName + ', ' + selectedApp?.firstName"></span>'s application to the next stage (<span class="font-semibold text-blue-600" x-text="getNextStageName(selectedApp?.status)"></span>)?</p><div class="flex gap-3 pt-2"><button type="button" @click="confirmStageModalOpen = false" class="flex-1 rounded-xl border border-gray-200 py-2.5 text-sm font-semibold text-gray-700 hover:bg-gray-50">Cancel</button><button type="button" @click="advanceApplicationStage()" class="flex-1 rounded-xl bg-blue-600 py-2.5 text-sm font-semibold text-white hover:bg-blue-700">Yes, Proceed</button></div></div></div>
<div x-show="rejectModalOpen" class="fixed inset-0 z-[70] flex items-center justify-center bg-black/40 p-4"><div  class="w-full max-w-md space-y-4 rounded-2xl border border-gray-200 bg-white p-6 shadow-2xl"><header class="flex items-start justify-between"><div class="flex items-center gap-3"><span class="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-red-50 text-red-600"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path stroke-linecap="round" d="M12 9v4m0 3h.01M10.3 4.5 2.7 18a2 2 0 0 0 1.7 3h15.2a2 2 0 0 0 1.7-3L13.7 4.5a2 2 0 0 0-3.4 0Z"/></svg></span><div><p class="text-[10px] font-bold uppercase tracking-wider text-gray-400">REGISTRATIONS</p><h3 class="text-base font-bold text-gray-900">Reject Application</h3></div></div><button type="button" @click="rejectModalOpen = false; confirmRejectStep = false" class="text-gray-400 hover:text-gray-700" aria-label="Close"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path stroke-linecap="round" d="m6 6 12 12M18 6 6 18"/></svg></button></header><div x-show="!confirmRejectStep"><p class="text-xs leading-relaxed text-gray-500">Select or write the reason for rejecting <span class="font-bold text-gray-900" x-text="selectedApp?.lastName + ', ' + selectedApp?.firstName + ' ' + (selectedApp?.middleName || '')"></span>'s application. This will be logged and visible to reviewing staff.</p><label class="mb-2 mt-3 block text-[11px] font-bold uppercase tracking-wider text-gray-400">REASON FOR REJECTION *</label><div class="mb-3 flex flex-wrap gap-2"><template x-for="pill in ['Duplicate in Masterlist','Unclear 1×1 Photo','Invalid ID / Address','Incomplete Proxy Docs']" :key="pill"><button type="button" @click="rejectReasonInput = pill" class="cursor-pointer rounded-lg border border-gray-200 px-2.5 py-1.5 text-xs text-gray-600 hover:border-red-300 hover:bg-red-50" x-text="pill"></button></template></div><textarea x-model="rejectReasonInput" rows="3" placeholder="State the specific reason for rejecting this application..." class="w-full resize-none rounded-xl border border-gray-200 p-3.5 text-sm text-gray-800 focus:border-red-500 focus:outline-none focus:ring-2 focus:ring-red-500/20"></textarea><div class="grid grid-cols-2 gap-3 pt-2"><button type="button" @click="rejectModalOpen = false" class="cursor-pointer rounded-xl border border-gray-200 bg-white py-2.5 text-sm font-semibold text-gray-700 hover:bg-gray-50">Cancel</button><button type="button" @click="confirmRejectStep = true" :disabled="rejectReasonInput.trim() === ''" :class="rejectReasonInput.trim() !== '' ? 'bg-red-600 hover:bg-red-700 text-white cursor-pointer' : 'bg-red-300 text-white cursor-not-allowed'" class="rounded-xl py-2.5 text-sm font-semibold transition-all">Confirm Rejection</button></div></div><div x-show="confirmRejectStep"><div class="space-y-1.5 rounded-xl border border-red-200 bg-red-50 p-4"><p class="text-sm font-bold text-red-800">Are you sure you want to reject this application?</p><p class="text-xs text-red-600">This action cannot be undone once confirmed. Reason logged: <span class="font-semibold italic" x-text="'&quot;' + rejectReasonInput + '&quot;'"></span></p></div><div class="grid grid-cols-2 gap-3 pt-2"><button type="button" @click="confirmRejectStep = false" class="rounded-xl border border-gray-200 bg-white py-2.5 text-sm font-semibold text-gray-700 hover:bg-gray-50">Cancel</button><button type="button" @click="finalizeRejection()" class="rounded-xl bg-red-600 py-2.5 text-sm font-semibold text-white hover:bg-red-700">Yes, Reject Application</button></div></div></div></div>
